mapper.select:

SELECT
    g.id AS id,
    g.creat_time AS `create_time`,
    g.desc AS  `desc`,
    g.price AS price,
    g.usage AS `usage`,
    g.send AS send,
    g.state AS goods_status,
    g.category AS goods_category,
    g.freight AS freight,
    g.first_picture AS goods_picture,
    u.account AS seller_account,
    u.head_url AS seller_avatar
FROM goods g
JOIN goods_category gc ON g.id = gc.goods_id
JOIN user u ON g.seller = u.id
WHERE 1=1




        AND gc.pricategory_id = #{query.condition.categoryIdList[0]}


        AND gc.seccategory_id = #{query.condition.categoryIdList[1]}


        AND gc.thicategory_id = #{query.condition.categoryIdList[2]}




        AND g.`usage` = #{query.condition.usage}




        AND g.creat_time BETWEEN #{query.condition.MinTime} AND #{query.condition.MaxTime}




        AND g.price >= #{query.condition.MinPrice}


        AND g.price <= #{query.condition.MaxPrice}




        AND g.send = #{query.condition.shippingWay}




        AND g.state = #{query.condition.auditStatus}



    ORDER BY


            g.creat_time ASC


            g.creat_time DESC


            g.price ASC


            g.price DESC


            g.creat_time DESC



    LIMIT #{query.pageSize} OFFSET #{query.offset}


SELECT
    COUNT(*)
FROM goods g
JOIN goods_category gc ON g.id = gc.goods_id
JOIN user u ON g.seller = u.id
WHERE 1=1




        AND gc.pricategory_id = #{query.condition.categoryIdList[0]}


        AND gc.seccategory_id = #{query.condition.categoryIdList[1]}


        AND gc.thicategory_id = #{query.condition.categoryIdList[2]}




        AND g.`usage` = #{query.condition.usage}




        AND g.creat_time BETWEEN #{query.condition.MinTime} AND #{query.condition.MaxTime}




        AND g.price >= #{query.condition.MinPrice}


        AND g.price <= #{query.condition.MaxPrice}




        AND g.send = #{query.condition.shippingWay}




        AND g.state = #{query.condition.auditStatus}
